// Consistent hash ring with virtual nodes (JavaScript)
import { createHash } from 'crypto';

class ConsistentHashRing {
  constructor(virtualNodes = 150) {
    this.virtualNodes = virtualNodes;
    this.ring = new Map();      // hash position → server name
    this.sortedKeys = [];       // sorted array of ring positions
  }

  _hash(key) {
    return parseInt(
      createHash('md5').update(key).digest('hex').slice(0, 8),
      16
    ); // 0..2^32
  }

  addServer(server) {
    for (let i = 0; i < this.virtualNodes; i++) {
      const vkey = `${server}#vnode${i}`;
      const pos = this._hash(vkey);
      this.ring.set(pos, server);
      this.sortedKeys.push(pos);
    }
    this.sortedKeys.sort((a, b) => a - b);
  }

  removeServer(server) {
    for (let i = 0; i < this.virtualNodes; i++) {
      const pos = this._hash(`${server}#vnode${i}`);
      this.ring.delete(pos);
    }
    this.sortedKeys = this.sortedKeys.filter(k => this.ring.has(k));
  }

  getServer(key) {
    if (this.sortedKeys.length === 0) throw new Error('No servers');
    const hash = this._hash(key);
    // Binary search for first position >= hash (clockwise)
    let lo = 0, hi = this.sortedKeys.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.sortedKeys[mid] < hash) lo = mid + 1;
      else hi = mid;
    }
    const pos = this.sortedKeys[lo % this.sortedKeys.length]; // wrap
    return this.ring.get(pos);
  }
}

// Usage
const ring = new ConsistentHashRing(150);
['cache-1', 'cache-2', 'cache-3'].forEach(s => ring.addServer(s));
console.log(ring.getServer('user:42'));   // e.g. 'cache-2'
console.log(ring.getServer('user:100'));  // e.g. 'cache-1'
ring.addServer('cache-4');               // only ~25% of keys remapped
console.log(ring.getServer('user:42'));  // likely still 'cache-2'

// Key properties of consistent hashing

// 1. Minimal disruption on topology change
//    N = current servers, adding 1 server remaps ~1/(N+1) keys
//    Removing 1 server remaps ~1/N keys (taken by successor)
const remapFraction = (currentServers) => 1 / (currentServers + 1);
console.log(`Adding server 4 remaps ~${(remapFraction(3) * 100).toFixed(0)}% of keys`);
// → Adding server 4 remaps ~25% of keys

// 2. Naive modulo hashing for comparison — full remap on any change
const naiveServer = (key, n) => hash(key) % n;
// Adding 1 server: nearly all keys hash to new servers

// 3. Virtual nodes improve load balance
//    With V=1: possible 60% arc on one server (hot spot)
//    With V=150: max imbalance ~2-3% in practice

// 4. Replication with consistent hashing
//    For replication factor R, a key is stored on R consecutive
//    ring nodes (clockwise from the key's hash position)
function getReplicaServers(ring, key, replicaCount) {
  const servers = [];
  const startPos = ring._hash(key);
  // Walk clockwise, collect R distinct servers
  for (const pos of ring.sortedKeys) {
    if (pos >= startPos && !servers.includes(ring.ring.get(pos))) {
      servers.push(ring.ring.get(pos));
    }
    if (servers.length === replicaCount) break;
  }
  return servers; // [primary, replica1, replica2]
}

